PriorityQueue<Integer> minHeap = new PriorityQueue<>();
for (int x : A) {
    minHeap.add(x);
}
int total = 0;
while (minHeap.size() > 1) {
    int a = minHeap.poll();
    int b = minHeap.poll();
    total += a + b;
    minHeap.add(a + b);   // the merged rope re-enters the pool
}
return total;

