PriorityQueue<ListNode> pq = new PriorityQueue<>((x, y) -> x.val - y.val);
for (ListNode head : lists) {
    if (head != null) {
        pq.add(head);
    }
}
ListNode dummy = new ListNode(0), tail = dummy;
while (!pq.isEmpty()) {
    ListNode node = pq.poll();
    tail.next = node;
    tail = node;
    if (node.next != null) {
        pq.add(node.next);   // push the successor, not the whole list
    }
}
return dummy.next;

