// children of i are 2i+1, 2i+2; parent of i is (i-1)/2
private void siftDown(int[] heap, int n, int i) {
    int smallest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;
    if (left < n && heap[left] < heap[smallest]) {
        smallest = left;
    }
    if (right < n && heap[right] < heap[smallest]) {
        smallest = right;
    }
    if (smallest != i) {
        swap(heap, i, smallest);
        siftDown(heap, n, smallest);
    }
}
// build in O(N): for (int i = n/2 - 1; i >= 0; i--) siftDown(heap, n, i);

