    give[i] = 1;
}
for (int i = 1; i < n; i++) {                 // left to right
    if (A[i] > A[i - 1]) {
        give[i] = give[i - 1] + 1;
    }
}
for (int i = n - 2; i >= 0; i--) {            // right to left
    if (A[i] > A[i + 1]) {
        give[i] = Math.max(give[i], give[i + 1] + 1);
    }
}

